// src/components/ROI/tabs/ProjectStatusTab.js
import React, { useEffect, useMemo, useRef, useState } from "react";
import { useOutletContext } from "react-router-dom";
import axios from "axios";

export default function ProjectStatusTab() {
  // intakeNumber supplied by parent route (ProjectLeadROIEntry)
  const { intakeNumber } = useOutletContext();

  // --- Compact UI helpers / classes ---
  const labelCls = "text-sm text-gray-700";
  const inputCls = "border rounded px-2 py-1 text-sm";
  const selectCls = "border rounded px-2 py-1 text-sm";
  const areaCls = "border rounded px-2 py-1 text-sm";
  const sectionWrap = "border rounded-lg p-3 mb-3 bg-white";
  const sectionTitle =
    "tab-section tab-section-yellow !bg-yellow-50 !text-gray-800 !py-2 !px-3 !rounded mb-2";
  const grid2 = "grid grid-cols-1 md:grid-cols-2 gap-3";
  const grid3 = "grid grid-cols-1 md:grid-cols-3 gap-3";

  // dropdown options
  const deliveryModelOptions = ["FP", "T&M"];
  const timelineOptions = ["Yes", "No"];
  const projectStatusOptions = [
    "Confirmed - Not Started",
    "Active - Discovery/pre kickoff",
    "Active - Project Kick Off",
    "Active - BRD/SRD",
    "Active - Solution / Design",
    "Active - Construction",
    "Active - DIT",
    "Active - SIT",
    "Active - UAT",
    "Project On Hold",
    "Project Completed / Closed",
    "Project Cancelled",
    "TBD (Status not known)",
  ];
  const estimateStatusOptions = ["Sent", "Automation-OOS"];
  const funcAutomationOptions = ["yes", "no"];
  const automationStatusOptions = [
    { label: "---ACTIVE---", disabled: true },
    { label: "Automation Intake/assessment" },
    { label: "Automation Work NOT Started" },
    { label: "SRD/BRD Phase" },
    { label: "Automation Test Planning" },
    { label: "Test Design - ConformIQ" },
    { label: "Scripting & Dry Run - Robot / Selenium / UFT / SOA / Scriptless" },
    { label: "Test Execution  - DIT" },
    { label: "Test Execution  - SIT" },
    { label: "Test Execution  - UAT" },
    { label: "Test Execution  - Support" },
    { label: "Test Support (Post execution)" },
    { label: "Automation Closure Activities" },
    { label: "KT Tasks" },
    { label: "Automated Test Design - QA Self" },
    { label: "Automated Test Execution - QA Self" },
    { label: "---DORMANT / CLOSED---", disabled: true },
    { label: "Pending Go ahead for Execution" },
    { label: "Auto. Work On Hold" },
    { label: "Auto. Work Cancelled" },
    { label: "Auto. Work Not Started" },
    { label: "Auto. Work Completed" },
    { label: "Test Design - Support" },
  ];

  // --- State (prefilled from APIs) ---
  const [resources, setResources] = useState([]);

  const [details, setDetails] = useState({
    deliveryModel: "",
    timelinesAvailable: "",
    projectCurrentStatus: "",
  });

  const [stakeholders, setStakeholders] = useState({
    qaManager: "",
    functionalQeLead: "", // text input
    funcSme: "",          // text input
    automationLeadOrQeLead: "",
    offshoreLead: "",
    fteOrAutomationArchitect: "",
    itPm: "",
  });

  const [dates, setDates] = useState({
    autoStartDate: "",
    autoEndDate: "",
    implementationDate: "",
  });

  const [estimation, setEstimation] = useState({
    estimateDueDate: "",
    estimateSubmittedOn: "",
    estimateStatusOrOOS: "",
    assignedToOrDoneBy: "",
    estimateReviewedBy: "",
    funcAutomation: "",
    reasonIfOOSorNoNew: "",
    qaCostWithoutAuto: "",   // = manual_cost
    qaCostWithAuto: "",      // = manual_cost + automation_cost
    automationCost: "",      // derived helper to keep With/Without in sync
    targetedMinSavings: "",  // computed & uneditable
  });

  const [automationStatus, setAutomationStatus] = useState({
    currentStatus: "",
    comments: "",
  });

  const [deliverables, setDeliverables] = useState({
    testPlanLTW: false,
    qaChecklistFollowed: false,
    tcUpdateInALMConfluence: false,
    gitUpdate: false,
    dsr: false, // optional / not in the 11-field list but kept
    leSentToPMMonthly: false,
    masterRegUpdatedALM: false,
    masterDashboardUpdated: false,
    releaseHandover: false,
    projectClosureReport: false,
    roiRealizedIn: "",
    qeTransformed: false,
    shiftLeftFollowed: false,
  });

  const [saving, setSaving] = useState(false);
  const [saveErr, setSaveErr] = useState("");
  const [saveOk, setSaveOk] = useState("");

  const [snapshot, setSnapshot] = useState(null);

  // Prevent initial data load from overwriting user input on first keystroke
  const loadedRef = useRef(false);
  useEffect(() => {
    loadedRef.current = false; // reset guard when intake changes
  }, [intakeNumber]);

  // Initial data load (projects, resources, automationdeliverables)
  useEffect(() => {
    if (!intakeNumber) return;
    if (loadedRef.current) return; // do not re-apply server data after first successful load

    let mounted = true;
    const load = async () => {
      try {
        const [resProj, resRes, resDel] = await Promise.all([
          axios.get(`http://localhost:5000/api/projects/${intakeNumber}`),
          axios.get("http://localhost:5000/api/resourcefetch"),
          axios.get(`http://localhost:5000/api/automationdeliverables/${intakeNumber}`),
        ]);
        if (!mounted) return;

        const p = resProj.data || {};
        const names = Array.isArray(resRes.data?.resources)
          ? resRes.data.resources
          : Array.isArray(resRes.data)
          ? resRes.data
          : [];
        setResources(names);

        setDetails({
          deliveryModel: p.DeliveryModel || "",
          timelinesAvailable: p.TimeLineAvailable || "",
          projectCurrentStatus: p.project_status || "",
        });

        setStakeholders((s) => ({
          ...s,
          qaManager: p.QAManager || "",
          functionalQeLead: p.functional_qe_lead || "",
          funcSme: p.FuncSME || "",
          automationLeadOrQeLead: p.automation_qe_lead || "",
          offshoreLead: p.OffshoreLead || "",
          fteOrAutomationArchitect: p.FTE_Architect || "",
          itPm: p.ITPM || "",
        }));

        setDates({
          autoStartDate: p.AutoWorkStartDate || "",
          autoEndDate: p.AutoWorkEndDate || "",
          implementationDate: p.ImplementationDate || "",
        });

        // derive costs from DB
        const manual = p.manual_cost ?? "";
        const autoCost = p.automation_cost ?? "";
        const qaCostWithout = manual;
        const qaCostWith =
          manual !== "" || autoCost !== ""
            ? Number(manual || 0) + Number(autoCost || 0)
            : "";

        const minSavings =
          qaCostWithout !== "" && qaCostWith !== ""
            ? Number(qaCostWithout || 0) - Number(qaCostWith || 0)
            : p.PSEMinSavings || "";

        setEstimation({
          estimateDueDate: p.AutoEstimateDueDate || "",
          estimateSubmittedOn: p.AutoEstimateSubmittedOn || "",
          estimateStatusOrOOS: p.AutoEstimateStatus || "",
          assignedToOrDoneBy: p.EstimateAssignedTo || "",
          estimateReviewedBy: p.EstimateReviewedBy || "",
          funcAutomation: p.FuncAutomationScope || "",
          reasonIfOOSorNoNew: p.AutoOOSReason || "",
          qaCostWithoutAuto: qaCostWithout,
          qaCostWithAuto: qaCostWith,
          automationCost: autoCost,
          targetedMinSavings: minSavings,
        });

        setAutomationStatus({
          currentStatus: p.AutomationStatus || "",
          comments: p.Comments || "",
        });

        // load deliverables from automationdeliverables table
        const d = resDel?.data || {};
        setDeliverables({
          testPlanLTW: !!d.AutomationTestPlan,
          qaChecklistFollowed: !!d.Checklist,
          tcUpdateInALMConfluence: !!d.ALMupdate,
          gitUpdate: !!d.GITUpdate,
          dsr: !!d.DSR,
          leSentToPMMonthly: !!d.LESubmitted,
          masterRegUpdatedALM: !!d.RegressionTestLab,
          masterDashboardUpdated: !!d.DashboardMetric,
          releaseHandover: !!d.ReleaseHandover,
          projectClosureReport: !!d.ProjectClosure,
          roiRealizedIn: d.ROIMonth || "",
          qeTransformed: !!d.QETransformed,
          shiftLeftFollowed: !!d.ShiftLeft,
        });

        // snapshot for dirty detection
        setSnapshot({
          details: {
            deliveryModel: p.DeliveryModel || "",
            timelinesAvailable: p.TimeLineAvailable || "",
            projectCurrentStatus: p.project_status || "",
          },
          stakeholders: {
            qaManager: p.QAManager || "",
            functionalQeLead: p.functional_qe_lead || "",
            funcSme: p.FuncSME || "",
            automationLeadOrQeLead: p.automation_qe_lead || "",
            offshoreLead: p.OffshoreLead || "",
            fteOrAutomationArchitect: p.FTE_Architect || "",
            itPm: p.ITPM || "",
          },
          dates: {
            autoStartDate: p.AutoWorkStartDate || "",
            autoEndDate: p.AutoWorkEndDate || "",
            implementationDate: p.ImplementationDate || "",
          },
          estimation: {
            estimateDueDate: p.AutoEstimateDueDate || "",
            estimateSubmittedOn: p.AutoEstimateSubmittedOn || "",
            estimateStatusOrOOS: p.AutoEstimateStatus || "",
            assignedToOrDoneBy: p.EstimateAssignedTo || "",
            estimateReviewedBy: p.EstimateReviewedBy || "",
            funcAutomation: p.FuncAutomationScope || "",
            reasonIfOOSorNoNew: p.AutoOOSReason || "",
            qaCostWithoutAuto: qaCostWithout,
            qaCostWithAuto: qaCostWith,
            automationCost: autoCost,
            targetedMinSavings: minSavings,
          },
          automationStatus: {
            currentStatus: p.AutomationStatus || "",
            comments: p.Comments || "",
          },
          deliverables: {
            testPlanLTW: !!d.AutomationTestPlan,
            qaChecklistFollowed: !!d.Checklist,
            tcUpdateInALMConfluence: !!d.ALMupdate,
            gitUpdate: !!d.GITUpdate,
            dsr: !!d.DSR,
            leSentToPMMonthly: !!d.LESubmitted,
            masterRegUpdatedALM: !!d.RegressionTestLab,
            masterDashboardUpdated: !!d.DashboardMetric,
            releaseHandover: !!d.ReleaseHandover,
            projectClosureReport: !!d.ProjectClosure,
            roiRealizedIn: d.ROIMonth || "",
            qeTransformed: !!d.QETransformed,
            shiftLeftFollowed: !!d.ShiftLeft,
          },
        });

        loadedRef.current = true; // mark initial load complete
      } catch (e) {
        console.error("Failed to load project status data", e);
      }
    };
    load();
    return () => {
      mounted = false;
    };
  }, [intakeNumber]);

  // Keep "Targeted Min. Savings" in sync (uneditable)
  useEffect(() => {
    const qaCostWithout = Number(estimation.qaCostWithoutAuto || 0);
    const qaCostWith = Number(estimation.qaCostWithAuto || 0);
    const next = qaCostWithout - qaCostWith;
    if (String(next) !== String(estimation.targetedMinSavings)) {
      setEstimation((s) => ({ ...s, targetedMinSavings: next }));
    }
  }, [estimation.qaCostWithoutAuto, estimation.qaCostWithAuto, estimation.targetedMinSavings]);

  // Dirty flag for Save button
  const dirty = useMemo(() => {
    if (!snapshot) return false;
    const now = { details, stakeholders, dates, estimation, automationStatus, deliverables };
    return JSON.stringify(now) !== JSON.stringify(snapshot);
  }, [details, stakeholders, dates, estimation, automationStatus, deliverables, snapshot]);

  const resetBanners = () => {
    setSaveErr("");
    setSaveOk("");
  };

  const onSaveAll = async () => {
    resetBanners();
    if (!dirty) return;
    setSaving(true);
    try {
      const updates = [];
      const pushIfChanged = (table, column, newVal, oldVal) => {
        if (String(newVal ?? "") !== String(oldVal ?? "")) {
          updates.push({ table, column, value: newVal });
        }
      };

      // details -> projects
      pushIfChanged("projects", "DeliveryModel", details.deliveryModel, snapshot.details.deliveryModel);
      pushIfChanged("projects", "TimeLineAvailable", details.timelinesAvailable, snapshot.details.timelinesAvailable);
      pushIfChanged("projects", "project_status", details.projectCurrentStatus, snapshot.details.projectCurrentStatus);

      // stakeholders -> projects
      pushIfChanged("projects", "QAManager", stakeholders.qaManager, snapshot.stakeholders.qaManager);
      // text fields as requested
      pushIfChanged("projects", "functional_qe_lead", stakeholders.functionalQeLead, snapshot.stakeholders.functionalQeLead);
      pushIfChanged("projects", "FuncSME", stakeholders.funcSme, snapshot.stakeholders.funcSme);
      // remaining stakeholder fields
      pushIfChanged("projects", "automation_qe_lead", stakeholders.automationLeadOrQeLead, snapshot.stakeholders.automationLeadOrQeLead);
      pushIfChanged("projects", "OffshoreLead", stakeholders.offshoreLead, snapshot.stakeholders.offshoreLead);
      pushIfChanged("projects", "FTE_Architect", stakeholders.fteOrAutomationArchitect, snapshot.stakeholders.fteOrAutomationArchitect);
      pushIfChanged("projects", "ITPM", stakeholders.itPm, snapshot.stakeholders.itPm);

      // dates -> projects / projects_timeline
      pushIfChanged("projects", "AutoWorkStartDate", dates.autoStartDate, snapshot.dates.autoStartDate);
      pushIfChanged("projects", "AutoWorkEndDate", dates.autoEndDate, snapshot.dates.autoEndDate);
      pushIfChanged("projects_timeline", "ImplementationDate", dates.implementationDate, snapshot.dates.implementationDate);

      // estimation -> projects
      pushIfChanged("projects", "AutoEstimateDueDate", estimation.estimateDueDate, snapshot.estimation.estimateDueDate);
      pushIfChanged("projects", "AutoEstimateSubmittedOn", estimation.estimateSubmittedOn, snapshot.estimation.estimateSubmittedOn);
      pushIfChanged("projects", "AutoEstimateStatus", estimation.estimateStatusOrOOS, snapshot.estimation.estimateStatusOrOOS);
      pushIfChanged("projects", "EstimateAssignedTo", estimation.assignedToOrDoneBy, snapshot.estimation.assignedToOrDoneBy);
      pushIfChanged("projects", "EstimateReviewedBy", estimation.estimateReviewedBy, snapshot.estimation.estimateReviewedBy);
      pushIfChanged("projects", "FuncAutomationScope", estimation.funcAutomation, snapshot.estimation.funcAutomation);
      if (estimation.funcAutomation === "no") {
        pushIfChanged("projects", "AutoOOSReason", estimation.reasonIfOOSorNoNew, snapshot.estimation.reasonIfOOSorNoNew);
      }
      // costs and derived savings
      pushIfChanged("projects", "manual_cost", estimation.qaCostWithoutAuto, snapshot.estimation.qaCostWithoutAuto);
      pushIfChanged("projects", "automation_cost", estimation.automationCost, snapshot.estimation.automationCost);
      pushIfChanged("projects", "PSEMinSavings", estimation.targetedMinSavings, snapshot.estimation.targetedMinSavings);

      // automation status -> projects
      pushIfChanged("projects", "AutomationStatus", automationStatus.currentStatus, snapshot.automationStatus.currentStatus);
      pushIfChanged("projects", "Comments", automationStatus.comments, snapshot.automationStatus.comments);

      // deliverables -> automationdeliverables ("YES" when checked, "" when unchecked)
      pushIfChanged("automationdeliverables", "AutomationTestPlan", deliverables.testPlanLTW ? "YES" : "", snapshot.deliverables.testPlanLTW ? "YES" : "");
      pushIfChanged("automationdeliverables", "Checklist", deliverables.qaChecklistFollowed ? "YES" : "", snapshot.deliverables.qaChecklistFollowed ? "YES" : "");
      pushIfChanged("automationdeliverables", "ALMupdate", deliverables.tcUpdateInALMConfluence ? "YES" : "", snapshot.deliverables.tcUpdateInALMConfluence ? "YES" : "");
      pushIfChanged("automationdeliverables", "GITUpdate", deliverables.gitUpdate ? "YES" : "", snapshot.deliverables.gitUpdate ? "YES" : "");
      pushIfChanged("automationdeliverables", "LESubmitted", deliverables.leSentToPMMonthly ? "YES" : "", snapshot.deliverables.leSentToPMMonthly ? "YES" : "");
      pushIfChanged("automationdeliverables", "RegressionTestLab", deliverables.masterRegUpdatedALM ? "YES" : "", snapshot.deliverables.masterRegUpdatedALM ? "YES" : "");
      pushIfChanged("automationdeliverables", "DashboardMetric", deliverables.masterDashboardUpdated ? "YES" : "", snapshot.deliverables.masterDashboardUpdated ? "YES" : "");
      pushIfChanged("automationdeliverables", "ReleaseHandover", deliverables.releaseHandover ? "YES" : "", snapshot.deliverables.releaseHandover ? "YES" : "");
      pushIfChanged("automationdeliverables", "ProjectClosure", deliverables.projectClosureReport ? "YES" : "", snapshot.deliverables.projectClosureReport ? "YES" : "");
      pushIfChanged("automationdeliverables", "QETransformed", deliverables.qeTransformed ? "YES" : "", snapshot.deliverables.qeTransformed ? "YES" : "");
      pushIfChanged("automationdeliverables", "ShiftLeft", deliverables.shiftLeftFollowed ? "YES" : "", snapshot.deliverables.shiftLeftFollowed ? "YES" : "");

      if (updates.length === 0) {
        setSaving(false);
        return;
      }

      const payload = { intake_number: intakeNumber, updates };
      const resp = await axios.post("http://localhost:5000/api/projectmasterupdate", payload);

      if (resp.status === 200 && resp.data?.ok) {
        setSaveOk("Saved successfully.");
        setSnapshot({ details, stakeholders, dates, estimation, automationStatus, deliverables });
      } else {
        setSaveErr(resp.data?.error || "Update failed.");
      }
    } catch (e) {
      console.error("Save failed", e);
      setSaveErr("Save failed. See console for details.");
    } finally {
      setSaving(false);
    }
  };

  // small input builders
  const Text = ({ label, value, onChange, placeholder, type = "text", disabled = false }) => (
    <div className="flex flex-col">
      <span className={labelCls}>{label}</span>
      <input
        className={inputCls}
        type={type}
        value={value}
        onChange={(e) => onChange(e.target.value)}
        placeholder={placeholder}
        disabled={disabled}
      />
    </div>
  );

  const Select = ({ label, value, onChange, options, disabled = false }) => (
    <div className="flex flex-col">
      <span className={labelCls}>{label}</span>
      <select
        className={selectCls}
        value={value}
        onChange={(e) => onChange(e.target.value)}
        disabled={disabled}
      >
        <option value="">-- Select --</option>
        {options.map((o) =>
          typeof o === "string" ? (
            <option key={o} value={o}>{o}</option>
          ) : (
            <option key={o.label} value={o.label} disabled={!!o.disabled}>
              {o.label}
            </option>
          )
        )}
      </select>
    </div>
  );

  const Area = ({ label, value, onChange, placeholder, disabled = false }) => (
    <div className="flex flex-col md:col-span-2">
      <span className={labelCls}>{label}</span>
      <textarea
        className={areaCls}
        rows={3}
        value={value}
        onChange={(e) => onChange(e.target.value)}
        placeholder={placeholder}
        disabled={disabled}
      />
    </div>
  );

  const Check = ({ label, value, onChange }) => (
    <label className="inline-flex items-center gap-2 text-sm">
      <input type="checkbox" checked={!!value} onChange={(e) => onChange(e.target.checked)} />
      <span className="text-gray-700">{label}</span>
    </label>
  );

  return (
    <div className="tab-wrap">
      {/* Save All */}
      <div className="flex items-center justify-between mb-3">
        <div className="text-sm text-gray-600">
          {saveOk && <span className="text-green-700">{saveOk}</span>}
          {saveErr && <span className="text-red-700">{saveErr}</span>}
        </div>
        <button
          className="btn-red"
          onClick={onSaveAll}
          disabled={!dirty || saving}
          title={!dirty ? "No changes to save" : "Save updates"}
        >
          {saving ? "Saving..." : "<Save All>"}
        </button>
      </div>

      {/* 1) Project Details */}
      <div className={sectionWrap}>
        <div className={sectionTitle}>Project Details</div>
        <div className={grid3}>
          <Select
            label="Delivery model"
            value={details.deliveryModel}
            onChange={(v) => setDetails((s) => ({ ...s, deliveryModel: v }))}
            options={deliveryModelOptions}
          />
          <Select
            label="Project Timelines Available ?"
            value={details.timelinesAvailable}
            onChange={(v) => setDetails((s) => ({ ...s, timelinesAvailable: v }))}
            options={timelineOptions}
          />
          <Select
            label="Project Current Status"
            value={details.projectCurrentStatus}
            onChange={(v) => setDetails((s) => ({ ...s, projectCurrentStatus: v }))}
            options={projectStatusOptions}
          />
        </div>
      </div>

      {/* 2) Project Stakeholders */}
      <div className={sectionWrap}>
        <div className={sectionTitle}>Project Stakeholders</div>
        <div className={grid3}>
          <Text
            label="QA Manager"
            value={stakeholders.qaManager}
            onChange={(v) => setStakeholders((s) => ({ ...s, qaManager: v }))}
            placeholder="Name"
          />
          {/* Text inputs per request */}
          <Text
            label="Functional_qe_lead"
            value={stakeholders.functionalQeLead}
            onChange={(v) => setStakeholders((s) => ({ ...s, functionalQeLead: v }))}
            placeholder="Name"
          />
          <Text
            label="Func. SME"
            value={stakeholders.funcSme}
            onChange={(v) => setStakeholders((s) => ({ ...s, funcSme: v }))}
            placeholder="Name"
          />
          {/* Remaining as dropdowns backed by resources list */}
          <Select
            label="Automation Lead (old) / QE lead (new)"
            value={stakeholders.automationLeadOrQeLead}
            onChange={(v) => setStakeholders((s) => ({ ...s, automationLeadOrQeLead: v }))}
            options={resources}
          />
          <Select
            label="Offshore Lead Resource"
            value={stakeholders.offshoreLead}
            onChange={(v) => setStakeholders((s) => ({ ...s, offshoreLead: v }))}
            options={resources}
          />
          <Select
            label="FTE (old) / Automation Architect (new)"
            value={stakeholders.fteOrAutomationArchitect}
            onChange={(v) => setStakeholders((s) => ({ ...s, fteOrAutomationArchitect: v }))}
            options={resources}
          />
          <Text
            label="IT PM"
            value={stakeholders.itPm}
            onChange={(v) => setStakeholders((s) => ({ ...s, itPm: v }))}
            placeholder="Name"
          />
        </div>
      </div>

      {/* 3) Project Dates */}
      <div className={sectionWrap}>
        <div className={sectionTitle}>Project Dates</div>
        <div className={grid3}>
          <Text
            label="Auto. Work Start Date"
            type="date"
            value={dates.autoStartDate}
            onChange={(v) => setDates((s) => ({ ...s, autoStartDate: v }))}
          />
          <Text
            label="Auto. Work End Date"
            type="date"
            value={dates.autoEndDate}
            onChange={(v) => setDates((s) => ({ ...s, autoEndDate: v }))}
          />
          <Text
            label="Implementation Date"
            type="date"
            value={dates.implementationDate}
            onChange={(v) => setDates((s) => ({ ...s, implementationDate: v }))}
          />
        </div>
      </div>

      {/* 4) Automation Estimation */}
      <div className={sectionWrap}>
        <div className={sectionTitle}>Automation Estimation</div>
        <div className={grid3}>
          <Text
            label="Estimate Due Date"
            type="date"
            value={estimation.estimateDueDate}
            onChange={(v) => setEstimation((s) => ({ ...s, estimateDueDate: v }))}
          />
          <Text
            label="Estimate Submitted On"
            type="date"
            value={estimation.estimateSubmittedOn}
            onChange={(v) => setEstimation((s) => ({ ...s, estimateSubmittedOn: v }))}
          />
          <Select
            label="Estimate Status / OOS"
            value={estimation.estimateStatusOrOOS}
            onChange={(v) => setEstimation((s) => ({ ...s, estimateStatusOrOOS: v }))}
            options={estimateStatusOptions}
          />
          <Text
            label="Assigned to / Estimate Done by"
            value={estimation.assignedToOrDoneBy}
            onChange={(v) => setEstimation((s) => ({ ...s, assignedToOrDoneBy: v }))}
            placeholder="Name"
          />
          <Text
            label="Estimate Reviewed By"
            value={estimation.estimateReviewedBy}
            onChange={(v) => setEstimation((s) => ({ ...s, estimateReviewedBy: v }))}
            placeholder="Name"
          />
          <Select
            label="Func. Automation"
            value={estimation.funcAutomation}
            onChange={(v) => setEstimation((s) => ({ ...s, funcAutomation: v }))}
            options={funcAutomationOptions}
          />
          <Area
            label="Reason if OOS / No new Automation"
            value={estimation.reasonIfOOSorNoNew}
            onChange={(v) => setEstimation((s) => ({ ...s, reasonIfOOSorNoNew: v }))}
            placeholder="Enter reason"
            disabled={estimation.funcAutomation !== "no"}
          />
          <Text
            label="Total QA Cost (Without Automation)"
            type="number"
            value={estimation.qaCostWithoutAuto}
            onChange={(v) =>
              setEstimation((s) => ({
                ...s,
                qaCostWithoutAuto: v,
                qaCostWithAuto: String(Number(v || 0) + Number(s.automationCost || 0)),
              }))
            }
            placeholder="0"
          />
          <Text
            label="Total QA Cost (With Automation)"
            type="number"
            value={estimation.qaCostWithAuto}
            onChange={(v) =>
              setEstimation((s) => ({
                ...s,
                qaCostWithAuto: v,
                automationCost: String(Number(v || 0) - Number(s.qaCostWithoutAuto || 0)),
              }))
            }
            placeholder="0"
          />
          <Text
            label="Targeted Min. Savings"
            type="number"
            value={estimation.targetedMinSavings}
            onChange={() => {}}
            disabled
          />
        </div>
      </div>

      {/* 5) Automation Status */}
      <div className={sectionWrap}>
        <div className={sectionTitle}>Automation Status</div>
        <div className={grid2}>
          <Select
            label="Current Automation Status"
            value={automationStatus.currentStatus}
            onChange={(v) => setAutomationStatus((s) => ({ ...s, currentStatus: v }))}
            options={automationStatusOptions}
          />
          <Area
            label="Comments"
            value={automationStatus.comments}
            onChange={(v) => setAutomationStatus((s) => ({ ...s, comments: v }))}
            placeholder="Notes, risks, blockers..."
          />
        </div>
      </div>

      {/* 6) QE Deliverables */}
      <div className={sectionWrap}>
        <div className={sectionTitle}>QE Deliverables</div>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
          <Check
            label="Automation Test Plan / LTW"
            value={deliverables.testPlanLTW}
            onChange={(v) => setDeliverables((s) => ({ ...s, testPlanLTW: v }))}
          />
          <Check
            label="QA Checklist followed"
            value={deliverables.qaChecklistFollowed}
            onChange={(v) => setDeliverables((s) => ({ ...s, qaChecklistFollowed: v }))}
          />
          <Check
            label="Test Case update in ALM"
            value={deliverables.tcUpdateInALMConfluence}
            onChange={(v) => setDeliverables((s) => ({ ...s, tcUpdateInALMConfluence: v }))}
          />
          <Check
            label="GIT Update"
            value={deliverables.gitUpdate}
            onChange={(v) => setDeliverables((s) => ({ ...s, gitUpdate: v }))}
          />
          <Check
            label="DSR"
            value={deliverables.dsr}
            onChange={(v) => setDeliverables((s) => ({ ...s, dsr: v }))}
          />
          <Check
            label="LE Sent to PM (Monthly Once)"
            value={deliverables.leSentToPMMonthly}
            onChange={(v) => setDeliverables((s) => ({ ...s, leSentToPMMonthly: v }))}
          />
          <Check
            label="Master Regression Updated in ALM Library"
            value={deliverables.masterRegUpdatedALM}
            onChange={(v) => setDeliverables((s) => ({ ...s, masterRegUpdatedALM: v }))}
          />
          <Check
            label="Master Dashboard Updated"
            value={deliverables.masterDashboardUpdated}
            onChange={(v) => setDeliverables((s) => ({ ...s, masterDashboardUpdated: v }))}
          />
          <Check
            label="Release Handover"
            value={deliverables.releaseHandover}
            onChange={(v) => setDeliverables((s) => ({ ...s, releaseHandover: v }))}
          />
          <Check
            label="Project Closure Report"
            value={deliverables.projectClosureReport}
            onChange={(v) => setDeliverables((s) => ({ ...s, projectClosureReport: v }))}
          />
          <Text
            label="ROI Realized in which month"
            type="month"
            value={deliverables.roiRealizedIn}
            onChange={(v) => setDeliverables((s) => ({ ...s, roiRealizedIn: v }))}
          />
          <Check
            label="QE Transformed"
            value={deliverables.qeTransformed}
